use vstd::prelude::*;

verus! {
    fn solve(word: Vec<char>) -> (result: Vec<char>)
        requires
            word.len() > 0,
        ensures
            (result == "YES".chars().collect() ==> 
                (word.iter().all(|&ch| set_a.contains(&ch) || set_b.contains(&ch)))),
            (result == "NO".chars().collect() ==> 
                (word.iter().any(|&ch| (set_a.contains(&ch) && !is_in_set_a) || 
                (set_b.contains(&ch) && !is_in_set_b)))),
    {
        // Define the sets as arrays for easy membership checking
        let set_a: Vec<char> = vec!['A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N', 'T', 'V', 'W', 'X', 'Y', 'Z'];
        let set_b: Vec<char> = vec!['B', 'C', 'D', 'G', 'J', 'O', 'P', 'Q', 'R', 'S', 'U'];

        // Check if the first character belongs to Set A or Set B
        let is_in_set_a = set_a.contains(&word[0]);
        let is_in_set_b = set_b.contains(&word[0]);

        // Iterate through the word and check membership
        for &ch in &word {
            if is_in_set_a && !set_a.contains(&ch) {
                return "NO".chars().collect();
            }
            if is_in_set_b && !set_b.contains(&ch) {
                return "NO".chars().collect();
            }
        }

        // If we reach here, all characters are in the same set
        "YES".chars().collect()
    }
}
